from pathlib import Path
import h5py, scipy.io, pickle
for p in sorted(Path('data').rglob('*')):
    if not p.is_file():
        continue
    print(f'===== {p} =====')
    suf = p.suffix.lower()
    try:
        if suf in ['.nwb', '.h5', '.hdf5']:
            with h5py.File(p, 'r') as f:
                def walk(name, obj):
                    if name.count('/') <= 2:
                        print(name, 'GROUP' if isinstance(obj, h5py.Group) else f'DATASET shape={obj.shape} dtype={obj.dtype}')
                f.visititems(walk)
        elif suf == '.mat':
            m = scipy.io.loadmat(p)
            print(sorted([k for k in m.keys() if not k.startswith('__')])[:50])
        elif suf in ['.pkl', '.pickle']:
            obj = pickle.load(open(p, 'rb'))
            print(type(obj))
            if isinstance(obj, dict):
                print('keys', list(obj.keys())[:50])
        else:
            print('unhandled extension')
    except Exception as e:
        print('ERROR', e)
