from pathlib import Path
import h5py
for p in sorted(Path('data').rglob('*.nwb')):
    with h5py.File(p, 'r') as f:
        subj = f['general/subject/subject_id'][()].decode() if hasattr(f['general/subject/subject_id'][()], 'decode') else str(f['general/subject/subject_id'][()])
        sess = f['general/session_id'][()].decode() if hasattr(f['general/session_id'][()], 'decode') else str(f['general/session_id'][()])
        n_trials = None
        if 'intervals' in f:
            for k in f['intervals'].keys():
                if 'trial' in k.lower():
                    grp = f['intervals'][k]
                    if 'start_time' in grp:
                        n_trials = len(grp['start_time'])
        n_rois = None
        if 'processing/ophys/ImageSegmentation' in f:
            try:
                ps = f['processing/ophys/ImageSegmentation/PlaneSegmentation']
                if 'id' in ps:
                    n_rois = len(ps['id'])
            except Exception:
                pass
        if n_rois is None and 'processing/ophys/Fluorescence' in f:
            try:
                for k in f['processing/ophys/Fluorescence'].keys():
                    ds = f['processing/ophys/Fluorescence'][k]['data']
                    shape = ds.shape
                    n_rois = max(shape)
                    break
            except Exception:
                pass
        print({'file': str(p), 'subject': subj, 'session': sess, 'n_trials': n_trials, 'n_rois': n_rois})
